<?php
declare(strict_types=1);

namespace lobby\entity\minecraft;

use GlobalLogger;
use InvalidArgumentException;
use lobby\entity\custom\BasicNPC;
use lobby\entity\custom\CommandNPC;
use lobby\entity\custom\ConditionalContentNPC;
use lobby\entity\custom\IconMarker;
use lobby\entity\custom\RandomPhraseNPC;
use lobby\features\secret\SecretData;
use lobby\Lobby;
use lobby\utils\npc\Button;
use lobby\utils\PlayerUtils;
use NetherGames\NGEssentials\player\NGPlayer;
use NetherGames\NGEssentials\utils\SkinUtils;
use NetherGames\NGEssentials\utils\Utils;
use pocketmine\entity\Entity;
use pocketmine\entity\Location;
use pocketmine\entity\Skin;
use pocketmine\player\Player;
use pocketmine\utils\TextFormat;
use pocketmine\world\World;
use Symfony\Component\Filesystem\Path;
use Throwable;

class NPCDeserializer
{
    private const DEFAULT_SKIN = "";

    public static function deserializeAndSpawn(array $data, World $world): array
    {
        $entities = [];
        $geometry = Utils::getResourceContent(Path::join('skins', 'default', 'geometry_humanoid_custom.json'));

        foreach ($data as $entry) {
            try {
                $type = $entry["type"];
                $title = $entry["title"];

                $buttons = [];
                if (array_key_exists("buttons", $entry)) {
                    foreach ($entry["buttons"] as $button) {
                        $buttons[] = ($newButton = new Button($button["text"], self::resolveAction($button["action"], $button["arg"])));
                        if (array_key_exists("type", $button)) {
                            $newButton->setType($button["type"]);
                        }

                        if (array_key_exists("data", $button)) {
                            $newButton->setData($button["data"]);
                        }
                    }
                }

                if (array_key_exists("opening_sound", $entry)) {
                    $openingSound = $entry["opening_sound"];
                } else {
                    $openingSound = null;
                }

                if (array_key_exists("opening_pitch", $entry)) {
                    $openingPitch = $entry["opening_pitch"];
                } else {
                    $openingPitch = 1;
                }

                if (array_key_exists("position", $entry)) {
                    $location = self::decodeLocation($entry["position"], $world);
                    if (array_key_exists("skins", $entry)) {
                        $skinName = $entry["skins"][array_rand($entry["skins"])];
                        $path = Path::join("skins", "npcs", "lobby", $skinName);
                        $skinData = SkinUtils::getTextureFromString(Utils::getResourceContent($path));
                    } else {
                        $skinData = base64_decode(self::DEFAULT_SKIN);
                    }

                    $skin = new Skin(
                        $type . "_" . TextFormat::clean($title) . "_NPC",
                        $skinData,
                        geometryName: 'geometry.humanoid.custom',
                        geometryData: $geometry,
                    );
                    // this is just one NPC, we can spawn him right away
                    $entities[] = self::prepareAndSpawn(type: $type, title: $title, location: $location, buttons: $buttons, skin: $skin, openingSound: $openingSound, openingPitch: $openingPitch, entry: $entry);
                } elseif (array_key_exists("positions", $entry)) {
                    foreach ($entry["positions"] as $position) {
                        try {
                            $location = self::decodeLocation($position, $world);
                        } catch (Throwable $t) {
                            GlobalLogger::get()->error("Wrong location: " . var_export($position, true) . " \n");
                            continue;
                        }
                        if (array_key_exists("skins", $entry)) {
                            $skinName = $entry["skins"][array_rand($entry["skins"])];
                            $path = Path::join("skins", "npcs", "lobby", $skinName);
                            $skinData = SkinUtils::getTextureFromString(Utils::getResourceContent($path));
                        } else {
                            $skinData = base64_decode(self::DEFAULT_SKIN);
                        }

                        $skin = new Skin(
                            $type . "_" . TextFormat::clean($title) . "_NPC",
                            $skinData,
                            geometryName: 'geometry.humanoid.custom',
                            geometryData: $geometry,
                        );

                        $entities[] = self::prepareAndSpawn(type: $type, title: $title, location: $location, buttons: $buttons, skin: $skin, openingSound: $openingSound, openingPitch: $openingPitch, entry: $entry);
                    }
                }
            } catch (Throwable $t) {
                var_dump($t->getMessage() . " for " . var_export($entry, true));
            }
        }

        return $entities;
    }

    public static function resolveAction(string $identifier, string $arg): ?callable
    {
        return match ($identifier) {
            "archery_start" => function (Player $player) use ($arg) {
                /** @var NGPlayer $player */
                Lobby::getInstance()->getFeaturesManager()->findFreeRange((int)$arg)->addPlayer($player);
            },
            "noop" => static function (Player $player) {
            },
            "reach_checkpoint" => static function (Player $player) use ($arg) {
                Lobby::getInstance()->getCheckpointManager()->reachCheckpoint($player, $arg);
            },
            "token_activate" => static function (Player $player) use ($arg) {
                if (PlayerUtils::hasUnlockedToken($player, $arg)) return;
                switch ($arg) {

                    case SecretData::CLIFF:
                        $location = new Location(x: 297.5, y: 133, z: -155, world: $player->getWorld(), yaw: 0, pitch: 0);
                        break;
                    case SecretData::FESTIVAL:
                        $location = new Location(x: -140.5, y: 57, z: -208.5, world: $player->getWorld(), yaw: 0, pitch: 0);
                        break;
                    case SecretData::CAVE:
                        $location = new Location(x: 72.5, y: 7, z: 262.5, world: $player->getWorld(), yaw: 0, pitch: 0);
                        break;
                    default:
                        return;
                }

                $marker = new IconMarker(
                    location: $location,
                    tokenIdentifier: $arg,
                    collectable: true
                );

                $marker->addTo($player);
                $marker->spawnTo($player);
            },
            default => null,
        };

    }

    private static function decodeLocation(array $entry, World $world): Location
    {
        ["x" => $x, "y" => $y, "z" => $z] = $entry;
        if (array_key_exists("yaw", $entry)) {
            $yaw = $entry["yaw"];
        } else {
            $yaw = 0;
        }
        if (array_key_exists("pitch", $entry)) {
            $pitch = $entry["pitch"];
        } else {
            $pitch = 0;
        }

        return new Location($x, $y, $z, $world, $yaw, $pitch);
    }

    private static function prepareAndSpawn(string $type, string $title, Location $location, array $buttons, Skin $skin, ?string $openingSound, ?int $openingPitch, array $entry): Entity
    {
        switch ($type) {
            case "Basic":
                $content = $entry["content"];
                $npc = new BasicNPC(content: $content, title: $title, location: $location, skin: $skin, buttons: $buttons, openingSound: $openingSound, openingPitch: $openingPitch);
                break;
            case "Conditional":
                $condition = $entry["condition"];
                $conditionName = $condition["name"];
                $conditionArg = $condition["arg"];
                $conditionResultMaps = $condition["results"];
                $npc = new ConditionalContentNPC(idx: $conditionName, conditionArgument: $conditionArg, conditionMapping: $conditionResultMaps
                    , title: $title, location: $location, skin: $skin, openingSound: $openingSound, openingPitch: $openingPitch);
                break;
            case "MultiPhrase":
                $phrases = $entry["phrases"];
                $npc = new RandomPhraseNPC(phrases: $phrases, title: $title, location: $location, skin: $skin, buttons: $buttons, openingSound: $openingSound, openingPitch: $openingPitch);
                break;
            case "Command":
                $command = $entry["command"];
                $npc = new CommandNPC(
                    command: $command,
                    location: $location,
                    skin: $skin
                );
                $npc->setNameTag($title);
                break;
            default:
                throw new InvalidArgumentException("Type must be one of Basic,Command,Conditional,MultiPhrase, is: $type");
        }

        GlobalLogger::get()->debug("Spawned: " . $title);

        $npc->setNameTagAlwaysVisible(true);
        $npc->spawnToAll();

        return $npc;
    }
}